/* Week 10: a cash ledger for two weeks of trade, one with developed-market partners and one
   with emerging-market partners. Learn, practise, plan each week, play the emerging-market
   week, compare, reflect. All costs come from week10_model.js. The demo and review pages do
   not load storage, identity or submission utilities. */
'use strict';
const $ = id => document.getElementById(id), M = PaymentLedger;
const DEMO = window.WEEK10_DEMO === true;
const TITLES = ['Understand','Example','Practise','Developed-market partners','Emerging-market partners','Play the week','Compare','Reflect and submit'];
const fmt = n => Math.abs(Number(n)).toLocaleString('en-US',{maximumFractionDigits:2});
const signed = n => (Number(n) < -1e-9 ? '−' : '') + fmt(n);
const usd = n => (Number(n) < -1e-9 ? '−' : '') + 'USD ' + fmt(n);
const pct = p => fmt(p * 100) + '%';
const lc = s => s.charAt(0).toLowerCase() + s.slice(1);
const PLAY_STEPS = [{days:[0],name:'Monday'},{days:[1],name:'Tuesday'},{days:[2],name:'Wednesday'},{days:[3],name:'Thursday'},{days:[4],name:'Friday'},{days:[5,6],name:'Saturday and Sunday'},{days:[7],name:'The following Monday'}];
const CLASS_WEEK = 'class', DM_WEEK = 'normal', MARKET_KEYS = ['dm','em'];
const blank = () => ({v:2,practice:{},dm:{route:null,line:null,first:null},em:{route:null,line:null,first:null},step:0,response:null,restarts:0,compare:{},help:{}});
let g = blank();
let charts = [], exploreTouched = false, explorerWeeksFor = null;
const planOf = m => g[m]?.route && g[m]?.line ? g[m].route + '-' + g[m].line : null;
const plan = () => planOf('em');

/* ---------- Practice ---------- */
const PRACTICE = {
 balance:{type:'Question 1 of 5 · End-of-day balance',title:'Read the ledger',negative:true,
  prompt:'The account starts Monday with USD 400,000. The firm pays its emerging-market supplier USD 1,000,000 through correspondent banks. The payment leaves the account on Monday. No other money moves on Monday. What is the balance at the end of Monday?',
  why:'This is the cash gap that the credit line must cover.',unit:'End-of-day balance on Monday (USD)',answer:-600000,tol:1,
  hint1:'A payment out decreases the balance on the day it leaves the account. With correspondent banks and an emerging-market supplier, the money leaves on Monday.',
  hint2:'End-of-day balance = start balance + money in − money out = 400,000 + 0 − 1,000,000.',
  solution:'400,000 − 1,000,000 = −600,000. The balance is USD 600,000 below zero, so the firm uses USD 600,000 of its credit line.',
  wrong:x=>x===600000?'The size is correct, but the balance is below zero. Type it with a minus sign: −600,000.':x===1400000?'A payment out decreases the balance. Subtract the payment.':'Start from 400,000 and subtract the 1,000,000 payment.'},
 interest:{type:'Question 2 of 5 · Interest',title:'Interest on the credit line',
  prompt:'With the correspondent route, the balance is −600,000 at the end of Monday, Tuesday and Wednesday. On Thursday the customer pays, and the balance stays positive for the rest of the week. Interest is 0.02% a day on a negative end-of-day balance. What is the total interest for the week?',
  why:'Each day with a negative balance adds interest. A slower route adds days.',unit:'Total interest (USD)',answer:360,tol:.5,
  hint1:'0.02% = 0.0002. Find the interest for one day first. Then count the days with a negative balance.',
  hint2:'Interest = credit used × 0.0002 × number of days = 600,000 × 0.0002 × 3.',
  solution:'One day: 600,000 × 0.0002 = USD 120. Three days (Monday, Tuesday and Wednesday): 3 × 120 = USD 360.',
  wrong:x=>x===120?'USD 120 is the interest for one day. The balance is negative for three days.':[36000,3600,3.6,36].includes(x)?'Check the decimal: 0.02% = 0.0002.':'Multiply 600,000 by 0.0002, then by the 3 days with a negative balance.'},
 route:{type:'Question 3 of 5 · Fee plus interest',title:'Compare the two routes for an emerging-market supplier',
  prompt:'With emerging-market partners, the correspondent route costs a USD 200 fee plus USD 360 interest in a normal week. The stablecoin bridge costs a USD 300 fee. It leaves on Wednesday, so the balance is −600,000 only at the end of Wednesday. Both plans have the same credit line. How much more does the correspondent route cost than the stablecoin bridge?',
  why:'This is the route decision for emerging-market partners in a week with no shocks.',unit:'Extra cost of the correspondent route (USD)',answer:140,tol:.5,
  hint1:'First find the interest for the stablecoin bridge: one day at −600,000.',
  hint2:'Difference = (200 + 360) − (300 + 600,000 × 0.0002 × 1).',
  solution:'Correspondent: 200 + 360 = USD 560. Stablecoin: 300 + 120 = USD 420. Difference: 560 − 420 = USD 140. The higher fee buys two fewer days of credit. With developed-market partners, the correspondent payment also leaves on Wednesday. Both routes then use one day of credit, and the correspondent route is USD 200 cheaper.',
  wrong:x=>Math.abs(x)===100?'That compares only the fees. Add the interest for each route.':x===560||x===420?'That is the cost of one route. Subtract the stablecoin cost from the correspondent cost.':x===-140?'The correspondent route costs more, so the answer is positive: 140.':x===40?'Check the correspondent fee: it is USD 200 for an emerging-market supplier.':'Add fee and interest for each route, then subtract.'},
 gap:{type:'Question 4 of 5 · A new cash gap',title:'A shock: the customer pays late',negative:true,
  prompt:'Now the emerging-market customer’s payment is held until next Monday. The firm uses the stablecoin bridge, so the balance is −600,000 at the end of Wednesday and Thursday. On Friday, payroll of USD 300,000 leaves the account. Assume that the credit line is large enough. What is the balance at the end of Friday?',
  why:'Compare this gap with the two credit lines: USD 600,000 and USD 1,000,000.',unit:'End-of-day balance on Friday (USD)',answer:-900000,tol:1,
  hint1:'No money arrives on Thursday or Friday. Payroll decreases the balance again.',
  hint2:'Friday balance = Thursday balance − payroll = −600,000 − 300,000.',
  solution:'−600,000 − 300,000 = −900,000. A USD 600,000 line cannot cover this, so the bank would hold payroll. A USD 1,000,000 line covers it.',
  wrong:x=>x===900000?'The size is correct, but the balance is below zero. Type it with a minus sign: −900,000.':x===-300000?'Start from Thursday’s balance of −600,000.':x===300000||x===900000-1200000?'The customer has not paid yet. Do not add the USD 1,200,000.':'Start from −600,000 and subtract payroll.'},
 line:{type:'Question 5 of 5 · Expected saving',title:'Is the large line worth its fee?',
  prompt:'The large line costs USD 200 more than the small line. With the small line, the firm buys an urgent line increase for USD 1,000 in any week when the customer’s payment is held. With emerging-market partners, these weeks have a probability of 25% in total. Interest is the same with either line. What is the expected saving from the large line, after its extra fee?',
  why:'This is the credit line decision before you know which week will happen.',unit:'Expected saving from the large line (USD)',answer:50,tol:.5,
  hint1:'The large line avoids the USD 1,000 urgent fee in 25% of weeks. It costs USD 200 more in every week.',
  hint2:'Expected saving = probability × urgent fee − extra line fee = 0.25 × 1,000 − 200.',
  solution:'0.25 × 1,000 = USD 250 of urgent fees avoided on average. 250 − 200 = USD 50. With developed-market partners, held weeks have a probability of 5%: 0.05 × 1,000 − 200 = −USD 150. With those partners, the small line costs less on average.',
  wrong:x=>x===250?'Now subtract the extra line fee of USD 200.':x===800?'Weight the urgent fee by its probability, 25%.':x===-150?'That is the result for developed-market partners (5%). Use 25% for emerging-market partners.':x===-50?'Check the order: urgent fees avoided minus the extra fee.':'Multiply 1,000 by 0.25, then subtract 200.'}
};
// Lecture examples (slides 30–43). Shown in the optional treasury view only.
const EXTRA = {
 quote:{title:'Fixed recipient amount',prompt:'Deliver exactly USD 100,000. Provider B quotes 7.80 HKD/USD, a 0.25% markup on that rate, and an HKD 80 sender fee. What is the total HKD debit?',unit:'Sender debit (HKD)',answer:782030,tol:1,hint1:'HKD/USD tells you to multiply USD by the exchange rate.',hint2:'HKD debit = USD received × HKD/USD × (1 + markup) + HKD fees.',solution:'100,000 × 7.80 = HKD 780,000. Markup = 780,000 × 0.0025 = HKD 1,950. Debit = 780,000 + 1,950 + 80 = HKD 782,030. The supplier receives the full USD 100,000.',wrong:()=>'Use 0.0025 for 0.25%. Multiply by HKD/USD. Fees are paid separately by the sender.'},
 loss:{title:'Expected production loss',prompt:'Provider B has a 5% chance of being late. A late payment causes HKD 100,000 of production loss; otherwise the loss is zero. What is the expected loss?',unit:'Expected production loss (HKD)',answer:5000,tol:1,hint1:'Multiply the loss if late by its probability.',hint2:'Expected production loss = probability late × loss if late.',solution:'0.05 × HKD 100,000 = HKD 5,000. Add this to the certain debit: 782,030 + 5,000 = HKD 787,030. A realised loss is either zero or 100,000.',wrong:()=>'5% is 0.05. This question asks for the expected loss, not the total sender debit.'},
 breakeven:{title:'Break-even loss per late payment',prompt:'Bank A costs HKD 785,080 and is late with probability 0.5%. Provider B costs HKD 782,030 and is late with probability 5%. At what loss per late payment do their expected totals tie?',unit:'Loss per late payment (HKD; 2 decimals)',answer:3050/.045,tol:1,hint1:'A costs more up front but has a lower probability of the same loss.',hint2:'Loss at a tie = (A debit − B debit) ÷ (B delay probability − A delay probability).',solution:'(785,080 − 782,030) ÷ (0.05 − 0.005) = 3,050 ÷ 0.045 = HKD 67,777.78. B is cheaper below this loss; A is cheaper above it.',wrong:()=>'Subtract the two probabilities in decimal form. A 4.5 percentage-point gap is 0.045, not 4.5.'},
 annual:{title:'Prefunding at an annual interest rate',prompt:'Commit USD 500,000 for 3 days. The annual opportunity cost is 5%. Use simple interest and a 360-day year. What is the cost?',unit:'Opportunity cost (USD; 2 decimals)',answer:500000*.05*3/360,tol:.02,hint1:'An annual rate must be scaled to three days.',hint2:'Cost = committed cash × annual rate × days ÷ days per year.',solution:'500,000 × 0.05 × 3 ÷ 360 = USD 208.33. The ledger game uses 0.02% a day, which is 7.2% a year on a 360-day basis.',wrong:()=>'Use the committed USD 500,000 and 3/360 of a year. Do not apply 5% as a daily rate.'},
 broker:{title:'Fixed sender budget',prompt:'Your total budget is HKD 78,000. The broker route deducts HKD 10 first, converts the remainder at 7.80 HKD/USD, then deducts a USD 2 commission. How many USD remain?',unit:'Net cash available (USD; 2 decimals)',answer:(78000-10)/7.8-2,tol:.02,hint1:'Subtract each fee while the balance is in that fee’s currency.',hint2:'Net USD = (HKD budget − HKD fee) ÷ (HKD/USD) − USD fee.',solution:'(78,000 − 10) ÷ 7.80 = USD 9,998.7179. Subtract USD 2: USD 9,996.72. The bank alternative gives (78,000 − 150) ÷ 7.84 = USD 9,929.85. The broker leaves USD 66.87 more, if both arrive in time.',wrong:()=>'Divide HKD by HKD/USD to obtain USD. Deduct the USD commission after conversion.'},
 netting:{title:'Net reciprocal invoices',prompt:'Europe owes Hong Kong EUR 500,000. Hong Kong owes Europe EUR 320,000 on the same date. Both claims may be netted. How much must Europe transfer?',unit:'Net Europe-to-Hong Kong payment (EUR)',answer:180000,tol:1,hint1:'Offset the smaller obligation against the larger one.',hint2:'Net payment = 500,000 − 320,000.',solution:'Europe sends EUR 180,000. At a proportional 0.4% fee, gross fees are (500,000 + 320,000) × 0.004 = EUR 3,280; net fees are 180,000 × 0.004 = EUR 720; saving = EUR 2,560.',wrong:()=>'Use the difference for the net transfer.'},
 cash:{title:'Cash needed before settlement',prompt:'A fund has USD 1M now, posts USD 0.8M collateral today, and must pay USD 2M tomorrow. A USD 3M receipt arrives on day 2. No credit is available. What extra cash is needed by tomorrow?',unit:'Extra cash (USD millions)',answer:1.8,tol:.01,hint1:'Only cash available before tomorrow’s payment can fund it.',hint2:'Shortfall = tomorrow’s payment − (initial cash − today’s collateral).',solution:'1 − 0.8 = USD 0.2M available. Tomorrow needs 2 − 0.2 = USD 1.8M extra. The later USD 3M receipt cannot fund an earlier payment without credit.',wrong:()=>'Enter millions, such as 1.8. Do not use the day-2 receipt to pay tomorrow’s bill.'}
};
const ALLQ = () => ({...PRACTICE,...EXTRA});
function practiceCard(id,q,{optional=false,open=false}={}){
 const o=open?' open':'';
 return `<article class="practice-card" id="card-${id}"><p class="practice-type">${optional?'Optional treasury practice':q.type}</p><h3>${q.title}</h3><p>${q.prompt}</p>${q.why?`<p class="why"><strong>Why it matters:</strong> ${q.why}</p>`:''}<label for="practice-${id}">${q.unit}<input id="practice-${id}" type="text" inputmode="${q.negative?'text':'decimal'}" autocomplete="off" spellcheck="false" aria-describedby="feedback-${id}" onkeydown="if(event.key==='Enter'){event.preventDefault();checkPractice('${id}');}"></label><small>${q.negative?'Type a minus sign (-) for a negative balance. ':''}Commas are fine.</small><div class="actions"><button type="button" onclick="checkPractice('${id}')">Check answer</button></div><p class="feedback" id="feedback-${id}" role="status" aria-live="polite"></p><details class="hint"${o} ontoggle="noteHelp('${id}','hint1',this.open)"><summary>Hint 1</summary><p>${q.hint1}</p></details><details class="hint"${o} ontoggle="noteHelp('${id}','hint2',this.open)"><summary>Hint 2 · the formula</summary><p>${q.hint2}</p></details><details class="solution-box"${o} ontoggle="noteHelp('${id}','solution',this.open)"><summary>Solution · free help</summary><p>${q.solution}</p>${optional?'':`<button type="button" onclick="reviewSolution('${id}')">I have read the solution</button>`}</details></article>`;
}
function parseNumber(raw){let s=String(raw).trim().replace(/usd|hkd|eur/ig,'').replace(/[,\s]/g,'').replace(/[−–—]/g,'-').replace(/%$/,'');let neg=false;if(/^\(.*\)$/.test(s)){neg=true;s=s.slice(1,-1);}if(!/^[-+]?(\d+\.?\d*|\.\d+)$/.test(s))return null;const x=Number(s);return neg?-x:x;}
function checkPractice(id){const q=ALLQ()[id];if(!q||(!DEMO&&gameSession.locked()))return;const x=parseNumber($('practice-'+id).value);const f=$('feedback-'+id);
 if(x===null){f.className='feedback try';f.textContent='Enter one number in the units shown. Your input is kept. The hints and the solution are below.';return;}
 const a=g.practice[id]||(g.practice[id]={attempts:[],correct:false,reviewed:false});a.attempts.push(x);a.attempts=a.attempts.slice(-5);a.correct=Math.abs(x-q.answer)<=q.tol;renderPractice(id);save();}
function reviewSolution(id){if(!DEMO&&gameSession.locked())return;g.practice[id] ||= {attempts:[],correct:false,reviewed:false};g.practice[id].reviewed=true;renderPractice(id);save();}
function noteHelp(id,kind,open){if(!open||(!DEMO&&gameSession.locked()))return;const h=g.help[id]||(g.help[id]={});h[kind]=(h[kind]||0)+1;}
function renderPractice(only){for(const [id,q] of Object.entries(ALLQ())){if(only&&id!==only||!$('feedback-'+id))continue;const a=g.practice[id],done=a?.correct||a?.reviewed,f=$('feedback-'+id);
 f.className='feedback '+(done?'ok':'try');const last=a?.attempts?.at(-1);
 f.textContent=a?.correct?'Correct. '+q.solution:a?.attempts?.length&&!a.correct?'Not yet. '+q.wrong(last)+(a.reviewed?' You have read the solution, so you can continue.':' Try again, or open the hints.'):a?.reviewed?'Solution read. You can continue.':'';
 $('card-'+id).classList.toggle('done',!!done);}}
const practiceDone = () => Object.keys(PRACTICE).every(id=>g.practice[id]?.correct||g.practice[id]?.reviewed);

/* ---------- Shared tables ---------- */
function flowText(f){return `${f.label} <span class="num ${f.amount<0?'neg':'pos'}">${f.amount<0?'−':'+'}${fmt(f.amount)}</span>`;}
function ledgerTable(s,upto=7,caption=''){const rows=s.rows.filter(r=>r.day<=upto);
 return `<div class="table-scroll"><table class="ledger"><caption>${caption||'Ledger'} · USD</caption><thead><tr><th>Day</th><th>Money in and out</th><th class="num">End-of-day balance</th><th class="num">Interest</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.end<0?'negative':''}${r.business?'':' weekend'}"><th scope="row">${r.label}</th><td>${[...r.notes.map(n=>`<span class="note-line">${n}</span>`),...r.flows.map(flowText),...r.held.map(h=>`<span class="held">${h.label} held by the bank (${fmt(h.amount)})</span>`)].join('<br>')||(r.business?'—':'Banks closed')}</td><td class="num ${r.end<0?'neg':''}">${signed(r.end)}</td><td class="num">${r.interest?fmt(r.interest):'0'}</td></tr>`).join('')}</tbody></table></div>`;}
const COST_LINES=[['routeFee','Route fee'],['lineFee','Credit line fee'],['urgentFee','Urgent line increase'],['interest','Interest'],['lateSupplier','Late supplier payment'],['latePayroll','Late payroll']];
function costTable(c,caption='Cost of the week'){return `<table class="cost-table"><caption>${caption} · USD</caption><tbody>${COST_LINES.map(([k,l])=>`<tr${c[k]?'':' class="zero"'}><th scope="row">${l}</th><td class="num">${fmt(c[k])}</td></tr>`).join('')}<tr class="total"><th scope="row">Total</th><td class="num">${fmt(c.total)}</td></tr></tbody></table>`;}
function sideBySide(a,b,labelA,labelB,caption){const line=(l,fa,fb,cls='')=>`<tr class="${cls}"><th scope="row">${l}</th><td class="num ${typeof fa==='number'&&fa<0?'neg':''}">${typeof fa==='number'?signed(fa):fa}</td><td class="num ${typeof fb==='number'&&fb<0?'neg':''}">${typeof fb==='number'?signed(fb):fb}</td></tr>`;
 return `<div class="table-scroll"><table class="compare-two"><caption>${caption} · USD</caption><thead><tr><th>Day</th><th class="num">${labelA}</th><th class="num">${labelB}</th></tr></thead><tbody>${a.rows.map((r,i)=>line(r.label+(r.held.length||b.rows[i].held.length?' *':''),r.end,b.rows[i].end)).join('')}${line('Days with a negative balance',String(a.negativeDays),String(b.negativeDays),'gap')}${COST_LINES.map(([k,l])=>a.costs[k]||b.costs[k]?line(l,fmt(a.costs[k]),fmt(b.costs[k])):'').join('')}${line('Total cost',fmt(a.costs.total),fmt(b.costs.total),'total')}</tbody></table></div>`;}
function calendarTable(){return `<div class="table-scroll"><table class="calendar"><caption>The week as planned, with either kind of partner · USD</caption><thead><tr><th>Day</th><th>Cash flow</th><th class="num">Amount</th></tr></thead><tbody><tr><th scope="row">Monday</th><td>Opening balance</td><td class="num">400,000</td></tr><tr><th scope="row">Wednesday</th><td>The supplier must <strong>receive</strong> this payment by the end of the day</td><td class="num neg">−1,000,000</td></tr><tr><th scope="row">Thursday</th><td>The customer’s payment arrives. It travels through correspondent banks.</td><td class="num pos">+1,200,000</td></tr><tr><th scope="row">Friday</th><td>Payroll (USD equivalent)</td><td class="num neg">−300,000</td></tr></tbody></table></div>`;}
function weeksTable(m){return `<div class="table-scroll"><table class="weeks stack-table"><caption>${M.MARKETS[m].name}: possible weeks · each week has one of these outcomes</caption><thead><tr><th>Week</th><th>What happens</th><th class="num">Probability</th></tr></thead><tbody>${M.weeks(m).map(w=>`<tr${m==='em'&&w.key===CLASS_WEEK?' class="class-week"':''}><td>${w.name}</td><td data-label="What happens">${w.text.replace(' This is the week you play.',m==='em'?' This is the week you play in Step 6.':'')}</td><td class="num" data-label="Probability">${pct(w.prob)}</td></tr>`).join('')}</tbody></table></div>`;}
const pausePct = m => pct(M.MARKETS[m].prob.pause);
const heldProb = m => (M.MARKETS[m].prob.held||0) + (M.MARKETS[m].prob.class||0);
function marketTable(){const t=(r,m)=>M.terms(r,m),row=(label,dm,em)=>`<tr><th scope="row">${label}</th><td data-label="${M.MARKETS.dm.name}">${dm}</td><td data-label="${M.MARKETS.em.name}">${em}</td></tr>`;
 return `<div class="table-scroll"><table class="market-table"><caption>What changes with the partners’ market · USD</caption><thead><tr><th>Item</th><th>${M.MARKETS.dm.name}</th><th>${M.MARKETS.em.name}</th></tr></thead><tbody>
 ${row('Partners','A component maker in the United States and a retailer in Europe.','A component maker and a retailer in emerging markets.')}
 ${row('Correspondent banks',`Fee USD ${fmt(t('corr','dm').fee)}. ${t('corr','dm').timing}`,`Fee USD ${fmt(t('corr','em').fee)}. ${t('corr','em').timing}`)}
 ${row('Stablecoin bridge',`Fee USD ${fmt(t('stable','dm').fee)}. Leaves on Wednesday, arrives within one hour. The off-ramp pauses in ${pausePct('dm')} of weeks.`,`Fee USD ${fmt(t('stable','em').fee)}. Same timing. The off-ramp pauses in ${pausePct('em')} of weeks: it has fewer local bank partners.`)}
 ${row('Customer payment held until next Monday (country risk)',`${pct(heldProb('dm'))} of weeks.`,`${pct(heldProb('em'))} of weeks. The customer’s bank cannot always buy USD, and more banks check the payment.`)}
 ${row('Customer never pays (nonpayment risk)',`${pct(M.MARKETS.dm.nonpay)} of trades. Expected loss: USD ${fmt(M.creditLoss('dm'))}.`,`${pct(M.MARKETS.em.nonpay)} of trades. Expected loss: USD ${fmt(M.creditLoss('em'))}.`)}
 </tbody></table></div>`;}

/* ---------- Step 1: Understand ---------- */
function routeCards(){return `<div class="grid-2"><article class="card route-card corr"><h4>${M.ROUTES.corr.name}</h4><p>${M.ROUTES.corr.how}</p><p>Each bank in the chain charges a fee and can add delay. The fee and the timing depend on the supplier’s bank: see the table below.</p></article><article class="card route-card stable"><h4>${M.ROUTES.stable.name}</h4><p>${M.ROUTES.stable.how}</p><p>Fee USD ${fmt(M.terms('stable','em').fee)} for either kind of supplier. It leaves your account on Wednesday and arrives within one hour.</p></article></div>`;}
function lineCards(){return `<div class="grid-2">${Object.values(M.LINES).map(l=>`<article class="card line-card"><h4>${l.name}: USD ${fmt(l.limit)}</h4><p>The balance can fall to −USD ${fmt(l.limit)}.</p><p>Fee for the week: <strong>USD ${fmt(l.fee)}</strong>, used or not.</p></article>`).join('')}</div>`;}
function intro(){return `<p class="guide"><strong>Your task:</strong> run the treasury of a Hong Kong electronics distributor. Pay every bill on time at the lowest total cost. You plan two weeks of trade: one with partners in developed markets and one with partners in emerging markets.</p>
<h3>The cash ledger</h3><p>The firm keeps one USD account at its Hong Kong bank. All suppliers and customers invoice in USD, so this exercise uses USD only.</p>
<ul class="terms"><li><strong>Ledger:</strong> the bank’s record of the account. Money in increases the balance. Money out decreases it.</li><li><strong>End-of-day balance:</strong> the balance after the day’s payments. A negative balance means that the firm uses its credit line.</li><li><strong>Credit line:</strong> a bank loan that the firm can use at any time, up to a limit. It is a form of working capital financing.</li><li><strong>Business day:</strong> Monday to Friday. Banks do not send payments on Saturday or Sunday.</li></ul>
<h3>The week as planned</h3>${calendarTable()}<p class="note">The timing problem: the supplier must be paid on Wednesday, but the customer pays on Thursday. On Wednesday the firm is USD 600,000 short.</p>
<h3>Two ways to pay the supplier</h3>${routeCards()}
<h3>Developed-market and emerging-market partners</h3><p>The ledger is the same with both kinds of partners. The bank chain and the customer’s risks are different.</p>${marketTable()}
<ul class="terms"><li><strong>Country risk:</strong> the customer has the money in local currency, but conditions in its country delay or stop the USD payment. An example is a shortage of USD at local banks.</li><li><strong>Nonpayment risk:</strong> the customer never pays, and the firm loses the invoice amount. The firm cannot fix this risk with a payment route or a credit line.</li></ul>
<h3>Two credit lines</h3><p>Select one line on Monday. Interest on the credit used is <strong>0.02% a day</strong> on a negative end-of-day balance: USD 20 a day for each USD 100,000. Saturday and Sunday count.</p>${lineCards()}
<h3>Other costs</h3><ul class="terms"><li><strong>Late supplier payment:</strong> USD 1,000 for each business day after Wednesday (late fee and a delayed next shipment).</li><li><strong>Late payroll:</strong> USD 5,000.</li><li><strong>Held payment:</strong> if a payment would take the balance below the line, the bank holds it. The bank sends it on the next business day with enough cash.</li></ul>
<p>Steps 4 and 5 list the possible weeks for each kind of partner, with their probabilities. All numbers are classroom assumptions.</p>
${DEMO?'':`<h3>Your participation details</h3><p>Enter these once. Credit follows the completed practice, two plans, the played week, two comparison answers and a reflection. Any plan and any use of help can earn credit.</p><div class="identity"><label>CUHK student ID<input id="input-student-id" inputmode="numeric" maxlength="10" autocomplete="off"><span class="field-error" id="identity-id-error"></span></label><label>Full name<input id="input-student-name" autocomplete="name" maxlength="160"><span class="field-error" id="identity-name-error"></span></label><label>Section<select id="input-section"><option value="">Select</option><option>A</option><option>B</option><option>C</option></select><span class="field-error" id="identity-section-error"></span></label></div>`}`;}

/* ---------- Step 2: Example ---------- */
function exampleHtml(){const cs=M.simulate('corr-small','normal','keep','em'),ss=M.simulate('stable-small','normal','keep','em'),dc=M.simulate('corr-small','normal','keep','dm'),ds=M.simulate('stable-small','normal','keep','dm'),hk=M.simulate('stable-small','held','keep','em'),hl=M.simulate('stable-large','held','keep','em');
 return `<article class="calc"><h3>Example: an emerging-market supplier paid through correspondent banks</h3><p>The supplier’s bank has no USD account in New York, so the payment takes 2 business days. The firm sends it on Monday and uses the small line (USD 600,000). Nothing goes wrong this week.</p>${ledgerTable(cs,7,'Emerging-market partners · correspondent banks + small line · normal week')}
<ol><li><strong>Monday:</strong> 400,000 − 1,000,000 = −600,000. The firm uses USD 600,000 of credit.</li><li><strong>Interest for one day:</strong> 600,000 × 0.0002 = USD 120. The balance is negative on Monday, Tuesday and Wednesday: 3 × 120 = <strong>USD 360</strong>.</li><li><strong>Thursday:</strong> −600,000 + 1,200,000 = 600,000. <strong>Friday:</strong> 600,000 − 300,000 = 300,000.</li><li><strong>Cost:</strong> route fee 200 + line fee 300 + interest 360 = <strong>USD ${fmt(cs.costs.total)}</strong>.</li></ol></article>
<article class="calc"><h3>Example: the same supplier paid by stablecoin bridge</h3><p>The stablecoin payment leaves on Wednesday and arrives within one hour. The firm keeps its cash for two more days.</p>${sideBySide(cs,ss,'Correspondent','Stablecoin','Emerging-market partners · normal week · small line')}<p>The stablecoin fee is USD 100 higher. It saves two days of interest (USD 240). With emerging-market partners, it costs USD ${fmt(cs.costs.total-ss.costs.total)} less in a normal week.</p></article>
<article class="calc"><h3>Example: a developed-market supplier</h3><p>Your bank and the US supplier’s bank both hold USD accounts at New York banks. The correspondent payment leaves on Wednesday and arrives the same day, for a USD 100 fee.</p>${sideBySide(dc,ds,'Correspondent','Stablecoin','Developed-market partners · normal week · small line')}<p>Both routes use one day of credit. The correspondent route costs USD ${fmt(ds.costs.total-dc.costs.total)} less. The stablecoin bridge adds fees and saves no days of credit.</p></article>
<article class="calc"><h3>Example: a shock makes the gap larger and longer</h3><p>Now the emerging-market customer’s payment is held until next Monday. The firm uses the stablecoin bridge. On Friday, payroll takes the balance to −900,000. The balance stays negative over the weekend.</p>${sideBySide(hk,hl,'Small line','Large line','Emerging-market partners · stablecoin bridge · customer payment held')}<p>* A payment is held by the bank on this day. With the small line, the bank holds payroll on Friday because −900,000 is below the −600,000 limit. Payroll is late: USD 5,000. With the large line, payroll leaves on time. Interest over Friday, Saturday and Sunday is 3 × 180 = USD 540.</p></article>
<p>A faster payment keeps cash in the account for longer, but only when the bank route is slow. A larger credit line covers a larger or longer gap. Step 3 asks you to make each calculation once.</p>`;}

/* ---------- Step 3: Practise ---------- */
function practiceHtml(open=false){return `<p>Make each calculation once. Each question has two hints and a free solution. You can continue after a correct answer or after you read the solution. Your input stays visible.</p>${Object.entries(PRACTICE).map(([id,q])=>practiceCard(id,q,{open})).join('')}`;}

/* ---------- Steps 4 and 5: plan with each kind of partner ---------- */
const PLAN_HINT = {
 dm:'With these partners, both routes leave on Wednesday, so they use the same days of credit. Compare the fees. For the line, use the solution to Question 5: here the customer’s payment is held in only 5% of weeks.',
 em:'Use your answers to Questions 3 and 5. Question 3 compares the two routes in a normal week. Question 5 compares the two lines on average. Then check the list of possible weeks: which shock affects your route?'
};
function option(m,name,value,title,detail){return `<label class="option"><input data-game-choice type="radio" name="${m}-${name}" value="${value}" onchange="selectPlan('${m}','${name}',this.value)"><span><strong>${title}</strong><small>${detail}</small></span></label>`;}
function marketStep(m){const k=M.MARKETS[m],t=r=>M.terms(r,m),routeDetail=r=>`Fee USD ${fmt(t(r).fee)} · leaves your account ${M.DAY_NAMES[t(r).send]} · supplier receives Wednesday`;
 return `<p>${m==='dm'?'This week the firm trades with partners in developed markets.':'This week the firm trades with partners in emerging markets. The ledger is the same as in Step 4. The banks and the risks are different.'} The supplier is ${k.supplier}. The customer is ${k.customer}.</p>
<div class="grid-2">${['corr','stable'].map(r=>`<article class="card route-card ${r}"><h4>${M.ROUTES[r].name}</h4><p>${t(r).timing}</p><dl><dt>Fee</dt><dd>USD ${fmt(t(r).fee)}</dd><dt>Your account is debited on</dt><dd>${M.DAY_NAMES[t(r).send]}</dd></dl></article>`).join('')}</div>
<h3>What can happen this week</h3>${weeksTable(m)}
<p class="caution"><strong>Nonpayment risk:</strong> in ${pct(k.nonpay)} of trades this customer never pays. Expected loss: ${pct(k.nonpay)} × 1,200,000 = USD ${fmt(M.creditLoss(m))}. Your route and your credit line do not change this loss, so the comparison of plans leaves it out.</p>
<fieldset class="choices"><legend>1. How will you pay the supplier?</legend><div class="options two">${option(m,'route','corr','Correspondent banks',routeDetail('corr'))}${option(m,'route','stable','Stablecoin bridge',routeDetail('stable'))}</div></fieldset>
<fieldset class="choices"><legend>2. Which credit line will you arrange on Monday?</legend><div class="options two">${option(m,'line','small','Small line: USD 600,000','Fee USD 300 for the week · balance can fall to −600,000')}${option(m,'line','large','Large line: USD 1,000,000','Fee USD 500 for the week · balance can fall to −1,000,000')}</div></fieldset>
<details class="hint" ontoggle="noteHelp('plan-${m}','hint',this.open)"><summary>Hint</summary><p>${PLAN_HINT[m]}</p></details>
<p id="${m}-feedback" class="feedback" role="status"></p><div id="${m}-result"></div>`;}
function selectPlan(m,kind,value){if(!M.MARKETS[m]||(!DEMO&&gameSession.locked()))return;const before=planOf(m);if(kind==='route'&&M.ROUTES[value])g[m].route=value;if(kind==='line'&&M.LINES[value])g[m].line=value;
 if(m==='dm'&&!g.dm.first&&planOf('dm'))g.dm.first=planOf('dm');
 if(m==='em'&&before&&plan()!==before&&g.step>0){g.step=0;g.response=null;g.restarts++;showMessage('');setFeedback('em-feedback','try','You changed your plan, so the week in Step 6 starts again.');}else setFeedback(m+'-feedback','','');
 renderMarket(m);save();}
function setFeedback(id,cls,text){const e=$(id);if(!e)return;e.className='feedback '+cls;e.textContent=text;}
function dmFeedback(s){const other=(s.route==='corr'?'stable':'corr')+'-'+s.line,o=M.simulate(other,DM_WEEK,'keep','dm'),d=o.costs.total-s.costs.total;
 const route=s.route==='corr'?`With the stablecoin bridge, this week would cost USD ${fmt(o.costs.total)}: USD ${fmt(d)} more. Both routes leave on Wednesday, so the stablecoin bridge saves no days of credit.`:`With correspondent banks, this week would cost USD ${fmt(o.costs.total)}: USD ${fmt(-d)} less. With these partners, the bank payment also leaves on Wednesday and arrives the same day.`;
 return route+(s.line==='large'?' The large line cost USD 200 more and was not necessary this week: the balance fell only to −600,000.':'');}
function renderMarket(m){document.querySelectorAll(`input[name="${m}-route"]`).forEach(e=>e.checked=e.value===g[m].route);document.querySelectorAll(`input[name="${m}-line"]`).forEach(e=>e.checked=e.value===g[m].line);
 const box=$(m+'-result');if(!box)return;const p=planOf(m);if(!p){box.innerHTML=`<p class="muted">Select a route and a line to see ${m==='dm'?'your week':'your plan in a normal week'}.</p>`;return;}
 const s=M.simulate(p,'normal','keep',m);
 if(m==='dm')box.innerHTML=`<h3>Your week with developed-market partners</h3><p class="week-end">This was a normal week, as in ${pct(M.MARKETS.dm.prob.normal)} of weeks with these partners. No payment was late.</p><p><strong>${M.planName(p)}.</strong> Largest credit used: USD ${fmt(s.peakCredit)}. Days with a negative balance: ${s.negativeDays}.</p>${ledgerTable(s,7,'Developed-market partners · normal week')}${costTable(s.costs,'Cost of the week')}<p class="feedback ${s.route==='corr'&&s.line==='small'?'ok':'try'}">${dmFeedback(s)}</p><p class="muted">You can change this plan and see the new ledger. Step 7 compares all plans over every possible week.</p>`;
 else box.innerHTML=`<h3>Your plan in a normal week</h3><p><strong>${M.planName(p)}.</strong> Largest credit used: USD ${fmt(s.peakCredit)}. Days with a negative balance: ${s.negativeDays}.</p>${ledgerTable(s,7,'Emerging-market partners · normal week, as planned')}${costTable(s.costs,'Cost in a normal week')}<p class="muted">Step 6 plays a week with shocks. The page does the arithmetic from now on.</p>`;}

/* ---------- Step 6: Play the emerging-market week ---------- */
const decisionNeeded = () => !!plan() && M.tuesdayDecisionNeeded(plan(), CLASS_WEEK, 'em');
const classSim = () => plan() ? M.simulate(plan(), CLASS_WEEK, g.response || 'keep', 'em') : null;
const RESPONSE_TEXT = {
 keep:'The bank will hold payroll on Friday until the customer’s money arrives next Monday. Late payroll: USD 5,000.',
 urgent:'The bank raises the line today. Urgent fee: USD 1,000. Interest is higher because the balance falls to −900,000.',
 delay:'You use no extra credit. The supplier is paid 3 business days late (Thursday, Friday and Monday): USD 3,000.'
};
const RESPONSE_FEEDBACK = {
 keep:'Payroll will be late. Late payroll costs USD 5,000, more than the other responses.',
 urgent:'The urgent fee is USD 1,000. On Monday, the large line cost only USD 200 more. Financing arranged before a shock costs less than urgent financing after it.',
 delay:'Delaying the supplier is a form of financing: the supplier waits for its money. Here it costs USD 3,000 in late fees, more than an urgent line increase.'
};
function storyFor(i,s){const corr=s.route==='corr',R=g.response,out=[];
 if(i===0){out.push(['event','The week starts with USD 400,000 in the account. Your partners this week are in emerging markets.']);
  out.push(corr?['event','You send USD 1,000,000 through correspondent banks. The chain has one more bank, so the payment takes 2 business days. Your bank debits the account today. The supplier should receive the money on Wednesday.']:['event','You keep the cash today. You will send the supplier payment by stablecoin bridge on Wednesday.']);
  if(corr)out.push(['event','The balance is −600,000. You use USD 600,000 of your credit line. Interest today: USD 120.']);}
 if(i===1){out.push(['news','<strong>News:</strong> the customer’s local bank cannot buy enough USD this week. The customer will pay the USD 1,200,000 next Monday, not Thursday. This is country risk: the customer has the money in local currency, but the USD payment is delayed.']);
  out.push(['event','Projection: on Friday, payroll will take the balance to −900,000.']);
  if(!decisionNeeded())out.push(['ok',`Your USD ${fmt(M.LINES[s.line].limit)} line covers this gap. No action is necessary.`]);
  else if(corr)out.push(['event','Your line covers only −600,000. Your supplier payment left on Monday, so you cannot use that cash again.']);
  else out.push(['event','Your line covers only −600,000. You still hold the USD 1,000,000 for the supplier.']);}
 if(i===2){out.push(['news','<strong>News:</strong> an intermediary bank in the correspondent chain was closed on Tuesday for a local holiday. Correspondent payments sent on Monday arrive one business day late.']);
  if(corr)out.push(['bad','Your supplier payment will arrive on Thursday, one business day late. Late cost: USD 1,000. The money left your account on Monday, so you cannot send it again by another route.']);
  else if(R==='delay')out.push(['bad','You do not pay the supplier today. Each business day late from Thursday costs USD 1,000.']);
  else out.push(['ok','The holiday does not affect your route. You send USD 1,000,000 by stablecoin bridge this morning. The supplier receives it within one hour, on time.']);}
 if(i===3){out.push(['event','The customer’s payment was due today. It has not arrived.']);if(corr)out.push(['event','The supplier receives USD 1,000,000 today, one business day late.']);}
 if(i===4){if(s.payrollLate)out.push(['bad','The bank holds payroll. Paying USD 300,000 would take the balance to −900,000, below your limit of −600,000. Staff are paid late: USD 5,000.']);
  else out.push(['event',`Payroll of USD 300,000 leaves the account. The balance is ${signed(s.rows[4].end)}.`]);}
 if(i===5)out.push(['event',s.rows[6].end<0?`Banks do not send payments on Saturday or Sunday. Interest still accrues every day: ${fmt(s.rows[5].interest)} + ${fmt(s.rows[6].interest)} = USD ${fmt(s.rows[5].interest+s.rows[6].interest)}.`:'Banks do not send payments on Saturday or Sunday. Your balance is positive, so there is no interest.']);
 if(i===6){out.push(['ok','The customer’s USD 1,200,000 arrives.']);if(s.payrollLate)out.push(['event','The bank releases payroll.']);if(R==='delay'&&!corr)out.push(['bad','You send the supplier payment by stablecoin bridge. It arrives 3 business days late: USD 3,000.']);
  out.push(['event',`The week ends. Total cost: USD ${fmt(s.costs.total)}.`]);}
 return out;}
function supplierStatus(s,day){if(s.supplierSent===null||s.supplierSent>day)return day>=M.P.deadline?'Not paid yet · late':'Not sent yet';
 if(s.supplierArrival>day)return 'Sent '+M.DAY_NAMES[s.supplierSent]+' · in the correspondent chain';
 return s.supplierLateDays?`Received ${s.supplierArrivalName} · ${s.supplierLateDays} business day${s.supplierLateDays>1?'s':''} late`:`Received ${s.supplierArrivalName} · on time`;}
function payrollStatus(s,day){if(day<4)return 'Due Friday';if(s.payrollPaid===4)return 'Paid Friday';if(s.payrollPaid>day)return 'Held by the bank · late';return 'Paid next Monday · late';}
function costsSoFar(s,day){const c={routeFee:s.supplierSent!==null&&s.supplierSent<=day?s.costs.routeFee:0,lineFee:s.costs.lineFee,urgentFee:day>=1?s.costs.urgentFee:0,
 interest:Math.round(s.rows.filter(r=>r.day<=day).reduce((a,r)=>a+r.interest,0)*100)/100,lateSupplier:s.supplierArrival<=day?s.costs.lateSupplier:0,latePayroll:day>=4?s.costs.latePayroll:0};
 c.total=Object.values(c).reduce((a,v)=>a+v,0);return c;}
function tuesdayDecision(s){const options=M.responses(s.route,CLASS_WEEK,'em'),locked=g.step>2||(!DEMO&&gameSession.locked());
 return `<fieldset class="choices tuesday"><legend>Your decision: how do you respond?</legend><div class="options">${options.map(k=>`<label class="option"><input data-game-choice type="radio" name="tuesday" value="${k}" ${g.response===k?'checked':''} ${locked?'disabled':''} onchange="selectResponse(this.value)"><span><strong>${M.RESPONSES[k].name}</strong><small>${RESPONSE_TEXT[k]}</small></span></label>`).join('')}</div></fieldset>
 <details class="hint" ontoggle="noteHelp('tuesday','hint',this.open)"><summary>Hint</summary><p>Compare the extra cost of each response: the fee or penalty, and the change in interest. One day of credit at −900,000 costs USD 180; at −600,000 it costs USD 120.</p></details>
 ${g.response?`<p class="feedback ${g.response==='urgent'?'ok':'try'}">${RESPONSE_FEEDBACK[g.response]} With this response, the week will cost USD ${fmt(s.costs.total)} in total.</p>`:''}`;}
function selectResponse(v){if(g.step!==2||!decisionNeeded()||!M.responses(g.em.route,CLASS_WEEK,'em').includes(v)||(!DEMO&&gameSession.locked()))return;g.response=v;renderPlay();save();}
function dayCard(i,s){const st=PLAY_STEPS[i];return `<article class="day-card"><p class="day-count">Day ${i+1} of ${PLAY_STEPS.length}</p><h3>${st.name}</h3>${storyFor(i,s).map(([k,t])=>`<p class="story ${k}">${t}</p>`).join('')}${i===1&&decisionNeeded()?tuesdayDecision(s):''}</article>`;}
function planStrip(s,day){return `<div class="plan-strip"><span><strong>Emerging-market partners</strong></span><span><strong>Your plan:</strong> ${M.planName(s.plan)}</span><span><strong>Credit line:</strong> USD ${fmt(s.rows[day].limit)}</span></div>`;}
function statusList(s,day){return `<ul class="status-list"><li><strong>Supplier:</strong> ${supplierStatus(s,day)}</li><li><strong>Payroll:</strong> ${payrollStatus(s,day)}</li><li><strong>Balance tonight:</strong> <span class="${s.rows[day].end<0?'neg':''}">${signed(s.rows[day].end)}</span></li></ul>`;}
function newsSoFar(step){const items=[];if(step>=3)items.push('Tuesday: the customer’s USD payment is delayed until next Monday.');if(step>=4)items.push('Wednesday: correspondent payments sent on Monday arrive one day late.');return items.length?`<div class="news-list"><strong>News this week</strong><ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul></div>`:'';}
function renderPlay(full=false){const area=$('play-area');if(!area)return;const p=plan();
 if(!p){area.innerHTML='<p>Select a route and a credit line for the emerging-market partners in Step 5 first.</p>';return;}
 if(!full&&g.step<1){g.step=1;if(!g.em.first)g.em.first=p;}
 const s=classSim(),step=full?PLAY_STEPS.length:Math.min(g.step,PLAY_STEPS.length),day=PLAY_STEPS[step-1].days.at(-1);
 const blocked=step===2&&decisionNeeded()&&!g.response;
 const cards=full?PLAY_STEPS.map((_,i)=>dayCard(i,s)).join(''):dayCard(step-1,s);
 area.innerHTML=planStrip(s,day)+(full?'':newsSoFar(step))+cards+statusList(s,day)+ledgerTable(s,day,full?'The whole week':'Your ledger so far')+costTable(costsSoFar(s,day),step===PLAY_STEPS.length?'Cost of your week':'Costs so far')
  +(step<PLAY_STEPS.length?`<div class="actions"><button class="primary" type="button" onclick="nextDay()" ${blocked?'disabled':''}>Go to ${PLAY_STEPS[step].name.replace(/^The /,'the ')} →</button>${blocked?'<span class="muted">Select a response first.</span>':''}</div>`:`<p class="week-end">This week had two shocks. Its probability was 5%. Step 7 shows how each plan does in every possible week, with both kinds of partners.</p>`);}
function nextDay(){if(!DEMO&&gameSession.locked())return;if(g.step===2&&decisionNeeded()&&!g.response){showMessage('Select a response to Tuesday’s news first. The hint can help.');return;}if(g.step<PLAY_STEPS.length)g.step++;showMessage('');renderPlay();save();$('play-area')?.scrollIntoView?.({block:'start'});}
const weekDone = () => !!plan() && g.step >= PLAY_STEPS.length;

/* ---------- Step 7: Compare ---------- */
const TINY = p => {const x=M.split(p);return (x.route==='corr'?'C':'S')+' + '+(x.line==='small'?'small':'large');};
const SHORT = p => {const x=M.split(p);return (x.route==='corr'?'Correspondent':'Stablecoin')+' + '+(x.line==='small'?'small line':'large line');};
const QUESTIONS = {
 dm:{text:'With developed-market partners, which Monday plan has the lowest expected cost?',answer:'corr-small',hint:'Read the “Expected cost” column of the developed-market table and find the smallest number.',
  right:'Correct. Correspondent banks + small line has the lowest expected cost: USD 603. The bank payment arrives the same day for a lower fee. Customer payments are rarely held, so the small line is enough on average.',
  wrong:p=>`The lowest expected cost is USD 603: correspondent banks + small line.${M.split(p)?.route==='stable'?' With these partners, the stablecoin bridge saves no days of credit and costs USD 200 more in fees.':' The large line costs USD 200 more every week. Held payments are rare (5% of weeks), so it saves only USD 50 of urgent fees on average.'}`},
 em:{text:'With emerging-market partners, which Monday plan has the lowest expected cost?',answer:'stable-large',hint:'Read the “Expected cost” column of the emerging-market table and find the smallest number.',
  right:'Correct. Stablecoin bridge + large line has the lowest expected cost: USD 1,185. The stablecoin bridge avoids two days of credit and the correspondent delay. The large line covers the gap when the customer pays late, which happens in 25% of weeks.',
  wrong:p=>`The lowest expected cost is USD 1,185: stablecoin bridge + large line.${p==='stable-small'?' The small line is USD 200 cheaper in a normal week, but it needs an urgent increase (USD 1,000) in 25% of weeks.':' The correspondent route pays for two more days of credit, and a correspondent delay makes the supplier payment late.'}`}
};
function creditLossHtml(){return `<strong>Nonpayment risk is separate.</strong> Expected loss if the customer never pays: developed-market customer ${pct(M.MARKETS.dm.nonpay)} × 1,200,000 = USD ${fmt(M.creditLoss('dm'))}; emerging-market customer ${pct(M.MARKETS.em.nonpay)} × 1,200,000 = USD ${fmt(M.creditLoss('em'))}. A faster route or a larger line does not change whether the customer pays. To limit this loss, an exporter can use credit insurance, a confirmed letter of credit or payment in advance (Weeks 5 and 7).`;}
function compareHtml(){return `<p>Judge a plan by its cost in every possible week, weighted by probability. Then compare the two kinds of partners.</p><div id="compare-summary"></div>
<h3>Developed-market partners</h3><div id="compare-table-dm"></div><h3>Emerging-market partners</h3><div id="compare-table-em"></div><p class="muted">Bold: lowest cost in the column.</p>
<p class="caution">${creditLossHtml()}</p>
<figure class="chart-figure"><h3>Expected cost by plan, with each kind of partner</h3><div class="chart"><canvas id="compare-chart" role="img" aria-label="Expected cost of each Monday plan with developed-market and emerging-market partners, and the cost of the emerging-market week played; exact values in the tables"></canvas></div><figcaption>Horizontal axis: the four Monday plans (on a phone: C = correspondent banks, S = stablecoin bridge). Vertical axis: USD cost of the week. Light green: expected cost with developed-market partners. Teal: expected cost with emerging-market partners. Red: the emerging-market week you played (both shocks). Values match the tables. The expected loss from nonpayment is not included.</figcaption></figure>
<h3>See any ledger</h3><p>Select the partners, a plan and a week. The page shows the ledger with the lowest-cost Tuesday response.</p><div class="explorer-controls three"><label>Partners<select id="explore-market" onchange="renderExplorer()">${MARKET_KEYS.map(m=>`<option value="${m}"${m==='em'?' selected':''}>${M.MARKETS[m].name}</option>`).join('')}</select></label><label>Plan<select id="explore-plan" onchange="exploreTouched=true;renderExplorer()">${M.PLAN_KEYS.map(p=>`<option value="${p}">${M.planName(p)}</option>`).join('')}</select></label><label>Week<select id="explore-week" onchange="renderExplorer()"></select></label></div><div id="explorer"></div>
<h3>Two questions</h3>${Object.entries(QUESTIONS).map(([k,q],i)=>`<fieldset class="choices"><legend>${'AB'[i]}. ${q.text}</legend><div class="options two">${M.PLAN_KEYS.map(p=>`<label class="option"><input data-game-choice type="radio" name="q-${k}" value="${p}" onchange="answerCompare('${k}',this.value)"><span><strong>${M.planName(p)}</strong></span></label>`).join('')}</div></fieldset><p id="q-${k}-feedback" class="feedback" role="status"></p><details class="hint" ontoggle="noteHelp('q-${k}','hint',this.open)"><summary>Hint</summary><p>${q.hint}</p></details>`).join('')}
<p class="lesson">With developed-market partners, the bank route is fast and cheap, so a stablecoin bridge adds fees and saves nothing. With emerging-market partners, the bank chain is longer and slower, so the stablecoin bridge is relatively cheaper. Payments from emerging-market customers are also more likely to arrive late, so a larger credit line arranged in advance pays for itself. Neither tool protects the firm against a customer who never pays.</p>`;}
function answerCompare(k,v){if(!QUESTIONS[k]||!M.split(v)||(!DEMO&&gameSession.locked()))return;g.compare[k]=v;renderAnswers();save();}
function renderAnswers(){for(const [k,q] of Object.entries(QUESTIONS)){document.querySelectorAll(`input[name="q-${k}"]`).forEach(e=>e.checked=e.value===g.compare[k]);const v=g.compare[k];if(!$(`q-${k}-feedback`))continue;setFeedback(`q-${k}-feedback`,v?v===q.answer?'ok':'try':'',v?v===q.answer?q.right:'Not this plan. '+q.wrong(v):'');}}
function planTable(m){const t=M.table(m),ws=M.weeks(m),p=planOf(m);
 const minW=Object.fromEntries(ws.map(w=>[w.key,Math.min(...t.map(r=>r.weeks[w.key].costs.total))])),minE=Math.min(...t.map(r=>r.expected));
 const head=w=>(m==='em'&&w.key===CLASS_WEEK?'The week you played: both shocks':m==='dm'&&w.key===DM_WEEK?'Normal week (your week)':w.name)+` (${pct(w.prob)})`;
 return `<div class="table-scroll"><table class="stack-table plans"><caption>${M.MARKETS[m].name}: cost of the week for each Monday plan · USD. In a week with a held customer payment, each plan uses its lowest-cost Tuesday response.</caption><thead><tr><th>Plan</th>${ws.map(w=>`<th class="num">${head(w)}</th>`).join('')}<th class="num">Expected cost</th></tr></thead><tbody>${t.map(r=>`<tr class="${r.plan===p?'your-choice':''}"><td>${r.name}${r.plan===p?' <span class="you">your plan</span>':''}</td>${ws.map(w=>{const c=r.weeks[w.key].costs.total;return `<td class="num${c===minW[w.key]?' lowest':''}" data-label="${head(w)}">${fmt(c)}</td>`;}).join('')}<td class="num expected${r.expected===minE?' lowest':''}" data-label="Expected cost">${fmt(r.expected)}</td></tr>`).join('')}</tbody></table></div>${p?`<div class="formula">Expected cost of your plan = ${ws.map(w=>`${w.prob.toFixed(2)} × ${fmt(M.best(p,w.key,m).costs.total)}`).join(' + ')} = <strong>USD ${fmt(M.expected(p,m))}</strong></div>`:''}`;}
function renderCompare(){const dp=planOf('dm'),ep=plan();
 if($('compare-summary'))$('compare-summary').innerHTML=dp&&ep?`<div class="verdict">Your two plans<small>Developed-market partners: ${M.planName(dp)}. Cost in your week (a normal week): USD ${fmt(M.simulate(dp,DM_WEEK,'keep','dm').costs.total)}. Expected cost: USD ${fmt(M.expected(dp,'dm'))}.</small><small>Emerging-market partners: ${M.planName(ep)}. Cost in the week you played: USD ${fmt(classSim().costs.total)}${g.response?` (Tuesday response: ${lc(M.RESPONSES[g.response].name)})`:''}. Expected cost: USD ${fmt(M.expected(ep,'em'))}.</small></div>`:'';
 for(const m of MARKET_KEYS)if($('compare-table-'+m))$('compare-table-'+m).innerHTML=planTable(m);
 if($('explore-plan')&&ep&&!exploreTouched)$('explore-plan').value=ep;
 renderExplorer();renderAnswers();drawChart();}
function renderExplorer(){const box=$('explorer');if(!box)return;const me=$('explore-market'),pe=$('explore-plan'),we=$('explore-week');const m=M.MARKETS[me?.value]?me.value:'em';
 const keys=M.weeks(m).map(w=>w.key);if(we&&explorerWeeksFor!==m){const cur=we.value;we.innerHTML=M.weeks(m).map(w=>`<option value="${w.key}">${w.name} (${pct(w.prob)})</option>`).join('');we.value=keys.includes(cur)?cur:'normal';explorerWeeksFor=m;}
 const pk=M.split(pe?.value)?pe.value:'stable-large',wk=keys.includes(we?.value)?we.value:'normal',w=M.week(wk);
 const s=M.best(pk,wk,m);box.innerHTML=`<p><strong>${M.MARKETS[m].name} · ${M.planName(pk)} · ${w.name}.</strong> ${w.text.replace(' This is the week you play.','')}${w.held&&s.response!=='keep'?` Tuesday response: ${lc(M.RESPONSES[s.response].name)}.`:''}</p>${ledgerTable(s,7,'Ledger')}${costTable(s.costs)}`;}
function drawChart(){charts.forEach(c=>c.destroy());charts=[];if(typeof Chart==='undefined'||!$('compare-chart'))return;const narrow=(window.innerWidth||1000)<600;Chart.defaults.font.size=14;Chart.defaults.color='#173346';const dm=M.table('dm'),em=M.table('em');
 charts.push(new Chart($('compare-chart'),{type:'bar',data:{labels:M.PLAN_KEYS.map(p=>narrow?TINY(p):SHORT(p)),datasets:[
  {label:'Developed market: expected cost',data:dm.map(r=>r.expected),backgroundColor:'#86BFA5'},
  {label:'Emerging market: expected cost',data:em.map(r=>r.expected),backgroundColor:'#146b66'},
  {label:'Emerging market: the week you played',data:em.map(r=>r.weeks[CLASS_WEEK].costs.total),backgroundColor:'#E39B93'}]},
  options:{responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{position:'bottom',labels:{boxWidth:18}},tooltip:{callbacks:{label:c=>`${c.dataset.label}: USD ${fmt(c.parsed.y)}`}}},scales:{x:{ticks:{autoSkip:false,maxRotation:0,callback:function(v){const l=this.getLabelForValue(v);return l.split(' + ');}}},y:{beginAtZero:true,title:{display:true,text:'Cost of the week (USD)'},ticks:{callback:v=>fmt(v)}}}}}));}

/* ---------- Step 8: Reflect ---------- */
function reflection(){return `<p>Use numbers from Steps 4 to 7. Write two or more sentences in your own words.</p><div id="reflection-evidence" class="evidence"></div><ol class="reflection-prompts"><li>Which plan did you select for each kind of partner? Give each plan’s expected cost and compare it with the lowest expected cost.</li><li>Why is the lowest-cost route different for the two kinds of partners? Use the fees and the days of credit.</li><li>The emerging-market customer is also more likely never to pay. Does a faster route or a larger credit line protect the firm against that loss? What could the firm use instead?</li></ol>
<details class="hint" ontoggle="noteHelp('reflection','hint',this.open)"><summary>Hint</summary><p>Start with numbers. For example: “With emerging-market partners, my plan’s expected cost is USD …. The lowest is USD … because ….” For Question 2, compare the days with a negative balance for each route in the Step 2 examples. For Question 3, read the box on nonpayment risk in Step 7.</p></details>
<label for="reflection-text">Your explanation<textarea id="reflection-text" rows="6" placeholder="I selected… With developed-market partners… With emerging-market partners… If the customer never pays…"></textarea></label><p>Any reasoned plan is accepted. Help is free.</p><p id="identity-review"></p>
<div class="actions"><button id="btn-submit-game" class="primary" onclick="submitGameResponse()">Submit reflection</button><button id="retry-game" onclick="gameSession.retry()" hidden>Retry same submission</button><button onclick="downloadRecord()">Download my response record</button></div><p id="submission-feedback" role="status" aria-live="polite"></p>
<p><strong>Before submission:</strong> your work is saved in this browser tab when storage is available. <strong>Sending:</strong> keep the tab open. <strong>Confirmed:</strong> a server receipt appears. <strong>Not confirmed:</strong> keep the tab open, retry the same submission or give your downloaded record to the TA. A sent request alone is not a confirmation.</p>
<p>A refresh keeps your work in this tab. If you close the tab, unconfirmed work can be lost. A receipt confirms storage. It does not confirm email delivery.</p><details><summary>Copyable response record</summary><textarea id="record-text" readonly aria-label="Response record"></textarea></details>`;}
function evidenceText(){const dp=planOf('dm'),ep=plan();if(!dp||!ep)return 'Select a plan in Steps 4 and 5.';const s=classSim();
 return `Developed-market partners: ${M.planName(dp)}. Cost in your week (a normal week): USD ${fmt(M.simulate(dp,DM_WEEK,'keep','dm').costs.total)}. Expected cost: USD ${fmt(M.expected(dp,'dm'))}. Emerging-market partners: ${M.planName(ep)}. Tuesday response: ${g.response?lc(M.RESPONSES[g.response].name):'none necessary'}. Cost in the week you played: USD ${fmt(s.costs.total)}. Expected cost: USD ${fmt(M.expected(ep,'em'))}. Lowest expected cost: correspondent banks + small line (USD ${fmt(M.expected('corr-small','dm'))}) with developed-market partners; stablecoin bridge + large line (USD ${fmt(M.expected('stable-large','em'))}) with emerging-market partners. Expected loss from nonpayment: USD ${fmt(M.creditLoss('dm'))} and USD ${fmt(M.creditLoss('em'))}.`;}
function updateRecord(){if(DEMO||!$('record-text'))return;const record=FINA3020Utils._readHistory().find(r=>r.submissionId===gameSession.state.submissionId);$('record-text').value=JSON.stringify(record||{activity:'Week 10 Payment Timing and the Cash Ledger',status:'Draft; no server confirmation',studentId:$('input-student-id').value,fullName:$('input-student-name').value,section:$('input-section').value,evidence:evidenceText(),responseText:$('reflection-text').value},null,2);}
function downloadRecord(){updateRecord();const a=document.createElement('a'),url=URL.createObjectURL(new Blob([$('record-text').value],{type:'application/json'}));a.href=url;a.download='week10-my-response.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

/* ---------- Session, navigation and submission ---------- */
function save(){if(!DEMO){gameSession.save();updateRecord();}}
function validateIdentity(){if(DEMO)return true;const valid=[/^\d{10}$/.test($('input-student-id').value.trim().replace(/\s/g,'')),!!$('input-student-name').value.trim()&&$('input-student-name').value.length<=160,['A','B','C'].includes($('input-section').value)];['id','name','section'].forEach((k,i)=>$('identity-'+k+'-error').textContent=valid[i]?'':['Enter one 10-digit CUHK ID.','Enter your full name (up to 160 characters).','Select section A, B or C.'][i]);return valid.every(Boolean);}
function go(n){if(n>1&&!validateIdentity()){showMessage('Check the highlighted participation details in Step 1.');return;}gameSession.navigate(n);}
function showMessage(text){if(DEMO)return;$('game-message').textContent=text;const e=$('stage-feedback-'+gameSession.state.stage);if(e){e.textContent=text;if(text)e.scrollIntoView?.({block:'nearest'});}}
function validate(n){if(n>=4&&!practiceDone())return 'Complete the five practice questions in Step 3. A correct answer or “I have read the solution” completes each one.';
 if(n>=5&&!planOf('dm'))return 'Select a route and a credit line for the developed-market partners in Step 4. Any plan is accepted.';
 if(n>=6&&!plan())return 'Select a route and a credit line for the emerging-market partners in Step 5. Any plan is accepted.';
 if(n>=7&&!weekDone())return 'Play the week to the end in Step 6. Use the “Go to” button to move from day to day.';
 if(n>=8&&!(g.compare.dm&&g.compare.em))return 'Answer both questions in Step 7. Any answer lets you continue; the feedback shows the correct plan.';return '';}
function render(){const n=gameSession.state.stage;$('intro-header').hidden=n!==1;renderPractice();if(n===4)renderMarket('dm');if(n===5)renderMarket('em');if(n===6)renderPlay();if(n===7)renderCompare();
 if(n===8){$('reflection-evidence').textContent=evidenceText();$('identity-review').textContent='Submitting for '+$('input-student-name').value+' · '+$('input-student-id').value+' · section '+$('input-section').value+'. Check these before you submit; use Step 1 to correct them.';updateRecord();}}
const FIELDS=['input-student-id','input-student-name','input-section','reflection-text',...Object.keys(PRACTICE).map(id=>'practice-'+id)];
function setChoices(c){if(c?.v!==2)return;const n=blank();
 for(const m of MARKET_KEYS){const x=c[m]||{};n[m].route=M.ROUTES[x.route]?x.route:null;n[m].line=M.LINES[x.line]?x.line:null;n[m].first=M.split(x.first)?x.first:null;}
 const ep=n.em.route&&n.em.line?n.em.route+'-'+n.em.line:null;
 n.step=ep&&Number.isInteger(c.step)?Math.max(0,Math.min(PLAY_STEPS.length,c.step)):0;n.restarts=Number.isInteger(c.restarts)?c.restarts:0;
 n.response=ep&&M.responses(n.em.route,CLASS_WEEK,'em').includes(c.response)&&M.tuesdayDecisionNeeded(ep,CLASS_WEEK,'em')?c.response:null;
 if(n.step>2&&M.tuesdayDecisionNeeded(ep,CLASS_WEEK,'em')&&!n.response)n.step=2;
 for(const k of Object.keys(QUESTIONS))if(M.split(c.compare?.[k]))n.compare[k]=c.compare[k];
 for(const id of Object.keys(PRACTICE)){const a=c.practice?.[id];if(a)n.practice[id]={attempts:Array.isArray(a.attempts)?a.attempts.filter(Number.isFinite).slice(-5):[],correct:a.correct===true,reviewed:a.reviewed===true};}
 if(c.help&&typeof c.help==='object')n.help=JSON.parse(JSON.stringify(c.help));g=n;}
const gameSession=DEMO?{state:{stage:1},save(){},locked:()=>false}:FINA3020GameSession.create({tab:'Payment_Route',version:'2026-11-04-week10-markets-v2',storageKey:'fina3020_game_Payment_Route_markets_v2',stageCount:TITLES.length,identity:FIELDS.slice(0,3),reflection:'reflection-text',fields:FIELDS,getChoices:()=>g,setChoices,validate,onAfterShow:render,onMessage:showMessage});
function payload(){const dp=planOf('dm'),ep=plan(),s=classSim(),d=M.simulate(dp,DM_WEEK,'keep','dm');return {mode:'Payment_Route',activityName:'Payment Timing and the Cash Ledger (Week 10)',week:10,
 question:'Plan two weeks of payments with a cash ledger, one with developed-market partners and one with emerging-market partners: select a payment route and a credit line, respond to shocks, and compare plans across possible weeks.',
 dmPlan:{plan:dp,name:M.planName(dp),first:g.dm.first},emPlan:{plan:ep,name:M.planName(ep),first:g.em.first},tuesdayResponse:g.response||'none needed',restarts:g.restarts,
 dmWeekCost:{...d.costs},emWeekCost:{...s.costs,supplierArrival:s.supplierArrivalName,payrollLate:s.payrollLate,peakCredit:s.peakCredit},
 expectedCost:{dm:M.expected(dp,'dm'),em:M.expected(ep,'em')},compareAnswers:{...g.compare,dmCorrect:g.compare.dm===QUESTIONS.dm.answer,emCorrect:g.compare.em===QUESTIONS.em.answer},
 practiceAnswers:g.practice,helpOpened:g.help};}
function submitGameResponse(){if(DEMO)return;if(!validateIdentity()){showMessage('Check your name, 10-digit CUHK ID and section in Step 1.');return;}const err=validate(TITLES.length);if(err){showMessage(err);return;}const text=$('reflection-text').value;if(!text.trim()){showMessage('Write your reflection above before you submit. Your work is kept.');return;}return gameSession.submit(payload()).then(updateRecord);}
function build(){const contents=[intro(),exampleHtml(),practiceHtml(),marketStep('dm'),marketStep('em'),'<div id="play-area" class="play-area"></div>',compareHtml(),reflection()];
 $('steps').innerHTML=TITLES.map((t,i)=>`<button id="step-${i+1}" onclick="gameSession.jump(${i+1})"><span>Step ${i+1}</span>${t}</button>`).join('');
 $('stages').innerHTML=contents.map((c,i)=>`<section class="panel" id="stage-${i+1}-panel" aria-labelledby="stage-${i+1}-title"><h2 id="stage-${i+1}-title">${i+1}. ${TITLES[i]}</h2>${c}<p id="stage-feedback-${i+1}" class="stage-feedback" role="status"></p><div class="actions section-nav">${i?`<button onclick="gameSession.jump(${i})">← Back</button>`:'<span></span>'}${i<TITLES.length-1?`<button class="primary" onclick="go(${i+2})">Continue to ${TITLES[i+1]} →</button>`:''}</div></section>`).join('');
 $('view-links').innerHTML=Object.entries(VIEWS).filter(([k])=>k!=='guide').map(([k,v])=>`<li><a href="10_payment_routing_demo.html?view=${k}" target="_blank" rel="noopener">${v.title}</a></li>`).join('')+'<li><a href="10_payment_routing_explained.html" target="_blank" rel="noopener">Review page: explanation and solutions</a></li>';}

/* ---------- Demonstration and review views (no identity, no record) ---------- */
function weekDemoHtml(){return `<p>The class week is an emerging-market week with two shocks: the customer’s USD payment is delayed until next Monday (Tuesday news), and correspondent payments sent on Monday arrive one day late (Wednesday news).</p><div class="explorer-controls"><label>Plan<select id="demo-plan" onchange="renderWeekDemo()">${M.PLAN_KEYS.map(p=>`<option value="${p}">${M.planName(p)}</option>`).join('')}</select></label><label>Tuesday response<select id="demo-response" onchange="renderWeekDemo()"></select></label></div><div id="play-area" class="play-area"></div>`;}
function renderWeekDemo(){const p=$('demo-plan').value,x=M.split(p);g.em.route=x.route;g.em.line=x.line;const need=M.tuesdayDecisionNeeded(p,CLASS_WEEK,'em'),sel=$('demo-response'),opts=need?M.responses(x.route,CLASS_WEEK,'em'):[];
 const cur=sel.value;sel.innerHTML=need?opts.map(k=>`<option value="${k}">${M.RESPONSES[k].name}</option>`).join(''):'<option value="">None necessary</option>';sel.disabled=!need;if(opts.includes(cur))sel.value=cur;g.response=need?sel.value:null;g.step=PLAY_STEPS.length;renderPlay(true);}
function plansDemoHtml(){return `<h2>${M.MARKETS.dm.name}</h2>${marketStep('dm')}<h2>${M.MARKETS.em.name}</h2>${marketStep('em')}`;}
function guideHtml(){return `<p>This page explains the Week 10 cash-ledger exercise and gives every solution. It records nothing.</p><h2>1. Understand</h2>${intro()}<h2>2. Example</h2>${exampleHtml()}<h2>3. Practice questions and solutions</h2>${practiceHtml(true)}<h2>4. Possible weeks with each kind of partner</h2>${weeksTable('dm')}${weeksTable('em')}<h2>5. Compare the plans</h2>${compareHtml()}`;}
function treasury(){return `<p>These are the lecture’s separate quote and treasury examples. Their Bank A / Provider B / Provider C labels are separate quotes. Amounts, fees and rates are given in each question. This workshop is optional.</p>${Object.entries(EXTRA).map(([id,q])=>practiceCard(id,q,{optional:true})).join('')}`;}
const VIEWS={
 understand:{title:'The firm, the ledger, the routes, the two kinds of partners and the credit lines',render:intro},
 example:{title:'Example: the ledger, the two routes in each market and a shock',render:exampleHtml},
 practice:{title:'Five practice questions with hints and solutions',render:()=>practiceHtml(false)},
 plan:{title:'Plan each week: developed-market and emerging-market partners',render:plansDemoHtml,after:()=>MARKET_KEYS.forEach(renderMarket)},
 week:{title:'Play the week: the emerging-market class week for any plan and response',render:weekDemoHtml,after:renderWeekDemo},
 compare:{title:'Compare the plans across possible weeks and markets',render:compareHtml,after:renderCompare},
 treasury:{title:'Treasury workshop: quotes, break-even, prefunding and cash',render:treasury},
 guide:{title:'Week 10 cash-ledger exercise: explanation and solutions',render:guideHtml,after:renderCompare}
};
const ALIASES={routes:'understand',markets:'plan',worked:'example',cost:'compare',probability:'compare',distribution:'compare'};
function demo(){const params=new URLSearchParams(window.location.search);let key=window.WEEK10_VIEW||params.get('view')||'compare';key=ALIASES[key]||key;if(!VIEWS[key])key='compare';const v=VIEWS[key];
 const banner=key==='guide'?'':`<div class="demo-banner"><p><strong>Instructor / review view · no identity, no stored progress, no participation record</strong></p><nav class="demo-nav">${Object.entries(VIEWS).filter(([k])=>k!=='guide').map(([k,x])=>`<a href="?view=${k}"${k===key?' aria-current="page"':''}>${x.title}</a>`).join('')}</nav></div>`;
 $('game-root').innerHTML=`${banner}<section class="panel"><h1>${v.title}</h1>${v.render()}</section><p><a href="10_payment_routing_game.html">Open the student exercise</a></p>`;v.after?.();}
document.addEventListener('DOMContentLoaded',()=>{if(DEMO){demo();return;}build();gameSession.start();FINA3020Utils.onDeliveryChange(updateRecord);});
window.addEventListener('pageshow',event=>{if(!DEMO&&event.persisted)render();});
